B.a1P=s([B.aeh],t.nN)
B.aew=new A.ms("1.4.0","2026-11-08","Dnevnik letenja z vnosom letov, statistiko in filtri.",B.a1P)
B.a2l=s(["E6B: za vsak izra\u010dun raz\u0161irljiv blok s postopkom in primerom na dejanskih \u0161tevilkah (telefon pod ra\u010dunalom, tablica in ra\u010dunalnik desno od njega)."],t.s)
B.aep=new A.hg("Orodja",B.a2l)
